func (p *Processor) ProcessAll(ctx context.Context, orders []Order) {
	jobs := make(chan Order)
	var wg sync.WaitGroup
	for i := 0; i < p.workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for o := range jobs {
				p.process(ctx, o)
			}
		}()
	}
	for _, o := range orders {
		jobs <- o
	}
	close(jobs)
	wg.Wait()
}

type Option func(*Client)

