	ctx, cancel := context.WithTimeout(ctx, 50*time.Millisecond)
	defer cancel()

	result := make(chan *Record)
	go func() {
		result <- c.slowFetch(id)
	}()

	select {
	case r := <-result:
		return r, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

